  // ────────────────────────────────────────────────────────────────────
  errors: {
    lede:
      'When the database refuses something it returns a SQLSTATE code. Most refusals are one of the codes below. Row-level security is the odd one out: on update and delete it doesn’t raise, it just affects **zero rows**.',
    codes: [
      { code: '42501', name: 'Not allowed', text: 'Raised by a function’s own permission check (e.g. “Only Hamrash platform admins can create schools”), or by RLS on **insert**.' },
      { code: 'RLS · 0 rows', name: 'Silently blocked', text: 'An update or delete the caller isn’t allowed to make simply changes nothing. The apps add `.select(\'id\')` and treat an empty result as “not allowed”.' },
      { code: '23503', name: 'Still in use', text: 'A foreign key blocks a delete, e.g. removing an arm that has students placed in it.' },
      { code: '23505', name: 'Already exists', text: 'A unique rule: duplicate section, class, arm, subject or session name; two teachers for one subject slot.' },
      { code: '23514', name: 'Breaks a rule', text: 'A check constraint or a trigger: blank name, end before start, term outside its session, a third assistant class teacher, a subject the arm doesn’t offer.' },
      { code: 'P0001', name: 'Plain-English refusal', text: 'Raised on purpose by a trigger or function with a human message, e.g. “This session is closed and can’t be changed”. Apps show this text as-is.' },
      { code: '22023', name: 'Bad input', text: 'A function argument is wrong, e.g. a number prefix that isn’t 2–8 letters or digits.' },
      { code: '28000', name: 'Not signed in', text: '“Not authenticated”: the request had no Clerk token. Usually means the app lost its session.' },
      { code: 'P0002', name: 'Not found', text: '“School not found” from `set_organization_status`.' },
    ],
    apps: [
      '**Hamrash Admin, classes and subjects:** `runRefusable` (`supabase_refusal.dart`) maps 23505 → duplicate message, 23503 → in-use message, 42501 and empty results → leaders-only message, 23514 → invalid message, and shows P0001 text verbatim.',
      '**Hamrash Admin, academic calendar:** P0001 and 23514 text is shown verbatim everywhere; creating a calendar also explains 42501 and 23505; everything else is “Could not … Try again.”',
      '**Hamrash Admin, school details:** a permission refusal (42501, or PGRST116 when RLS matched no row) reads “Only the owner can change the school’s details.”; bad values and P0001 are explained; anything else is a connection message.',
      '**Hamrash Admin, joining:** matches two exact messages (“This school is not currently active”, “You already have this role at this school”); anything else is a snackbar.',
      '**Platform Admin:** `friendlyError` shows our functions’ own 42501 sentences, replaces Postgres’s row-level-security 42501 with “Your account isn’t allowed to do that…”, every 23505 with “That already exists…”, and shows any other message raw.',
    ],
  },

